INSERT INTO `questions` (`id`, `subject_id`, `bank_soal_id`, `urutan`, `kelas`, `pertanyaan`, `img_pertanyaan`, `pil_a`, `img_a`, `pil_b`, `img_b`, `pil_c`, `img_c`, `pil_d`, `img_d`, `pil_e`, `img_e`, `kunci_jawaban`) VALUES
(3186, 72, 33, 0, '7B', 'Salah satu contoh perwujudan perbuatan kita di sekolah sebagai citra Allah  ....', NULL, 'menempatkan sampah pada tempatnya', NULL, 'membantu teman sebagai balas budi', NULL, 'menolong teman karena seiman', NULL, 'belajar sebagai kewajiban', NULL, '', NULL, 'A'),
(3187, 72, 33, 0, '7B', 'Allah menciptakan manusia itu menurut gambar-Nya, menurut gambar Allah diciptakan laki-laki dan perempuan diciptakan-Nya mereka . Hal demikian dapat kita baca dalam Kitabâ€¦ .', NULL, 'Bilangan', NULL, 'Ulangan ', NULL, 'Keluaran ', NULL, 'Kejadian ', NULL, '', NULL, 'D'),
(3188, 72, 33, 0, '7B', 'Menurut Kitab Kejadian 1:26-28, manusia diciptakan sebagai citra Allah, artinya ...  dan segambar dengan Allah sendiri.', NULL, 'Mirip', NULL, 'Serupa', NULL, 'Sewajah', NULL, 'Sewujud', NULL, '', NULL, 'B'),
(3189, 72, 33, 0, '7B', 'Cipta merupakan daya yang dimiliki manusia untuk dapat mengerti dan menyadari akan dirinya, alam sekitar, bahkan ....', NULL, 'penciptanya ', NULL, 'kebenaran ', NULL, 'kesucian ', NULL, 'dunia ', NULL, '', NULL, 'A'),
(3190, 72, 33, 0, '7B', 'Rasa selalu mendorong manusia untuk berbuat baik, jika melanggarnya, maka akan merasakan ....', NULL, 'senang dan lega', NULL, 'bangga dan puas', NULL, 'cemas dan menderita', NULL, 'prihatin dan marah ', NULL, '', NULL, 'C'),
(3191, 72, 33, 0, '7B', 'Menurut Kej 1:26-28, manusia dipanggil Allah untuk â€¦  bumi dan menaklukannya', NULL, 'menjaga', NULL, 'menguasai', NULL, 'memenuhi', NULL, 'merawatnya ', NULL, '', NULL, 'D'),
(3192, 72, 33, 0, '7B', 'Manusia sebagai citra Allah diangkat oleh Sang Pencipta sebagai tuan atasâ€¦.', NULL, 'langit dan bumi ', NULL, 'semua mahkluk di bumi ', NULL, 'semua yang yang berada di bawah bumi ', NULL, 'mahkluk yang kelihatan ', NULL, '', NULL, 'B'),
(3193, 72, 33, 0, '7B', 'Kekhasan manusia dibandingkan dengan ciptaan Tuhan yang lain yaitu â€¦ .', NULL, 'dapat berkomunikasi ', NULL, 'makan dan minum diolah ', NULL, 'tumbuh dan berkembang', NULL, 'dapat membedakan baik dan buruk ', NULL, '', NULL, 'D'),
(3194, 72, 33, 0, '7B', 'Sebagai wujud diri sebagai cirtra Allah, sebaiknya yang kita lakukan adalah ....', NULL, 'memberi tumpangan bila ada orang asing', NULL, 'bersikap adil kepada teman yang salah', NULL, 'senang menolong bila menguntungkan', NULL, 'berbalas budi kepada teman yang baik', NULL, '', NULL, 'B'),
(3195, 72, 33, 0, '7B', 'Tujuan Tuhan menganugerahi talenta kepada manusia berbeda-beda, supaya manusia â€¦.', NULL, 'adil dan seimbang ', NULL, 'ada perbedaan ', NULL, 'berkompetisi', NULL, 'bekerjasama ', NULL, '', NULL, 'A'),
(3196, 74, 34, 0, '7A', 'Komponen kebugaran jasmani yang berkaitan langsung dengan keterampilan untuk mengubah arah posisi tubuh secara cepat disebut...', NULL, 'Daya tahan', NULL, 'Kelincahan ', NULL, ' Kekuatan', NULL, ' Fleksibilitas ', NULL, 'Ketahanan', NULL, 'B'),
(3197, 74, 34, 0, '7A', 'Kemampuan sistem saraf dan otot untuk memadukan berbagai bentuk gerakan yang berbeda ke dalam satu pola gerak yang selaras dinamakan...', NULL, ' Kecepatan', NULL, ' Keseimbangan', NULL, 'Koordinasi', NULL, 'Daya ledak', NULL, ' Konsentrasi', NULL, 'C'),
(3198, 74, 34, 0, '7A', 'Kemampuan mempertahankan tubuh dalam posisi tetap seimbang, baik saat diam maupun bergerak, disebut...', NULL, 'Koordinasi', NULL, 'Kanelentur', NULL, 'Keseimbangan ', NULL, 'Daya tahan', NULL, 'Konsentrasi', NULL, 'C'),
(3199, 74, 34, 0, '7A', 'Apa definisi yang paling tepat mengenai umpan balik (feedback) dalam pembelajaran keterampilan gerak?', NULL, 'Penilaian akhir berupa angka rapor peserta didik', NULL, 'Informasi yang diterima seseorang tentang hasil atau pelaksanaan suatu gerakan yang telah dilakukan', NULL, 'Perintah mutlak dari guru agar siswa diam', NULL, 'Teori dasar sejarah olahraga', NULL, 'Penilaian harian untuk siswa', NULL, 'B'),
(3200, 74, 34, 0, '7A', 'Umpan balik yang bersumber dari dalam diri pelaku sendiri melalui alat indra (seperti rasa keseimbangan atau posisi tubuh) disebut...', NULL, 'Umpan balik ekstrinsik', NULL, 'Umpan balik verbal', NULL, 'Umpan balik internal', NULL, 'Umpan balik eksternal', NULL, 'Umpan balik intrinstik', NULL, 'C'),
(3201, 74, 34, 0, '7A', '	Fungsi utama dari umpan balik internal Adalah untuk melatih....', NULL, 'kepekaan tubuh ', NULL, 'komunikasi dengan tim', NULL, 'strategi permainan', NULL, 'kekuatan otot', NULL, ' keseimbanggan', NULL, 'A'),
(3202, 74, 34, 0, '7A', 'Panduan perbaikan yang berfungsi membantu\r\nmengetahui bagian gerakan yang sudah benar dan yang perlu diperbaiki dalam proses\r\npembelajaran keterampilan gerak disebut..\r\n', NULL, 'demonstrasi', NULL, 'progresi', NULL, 'umpan balik', NULL, ' aplikasi', NULL, ' strategi', NULL, 'B'),
(3203, 74, 34, 0, '7A', ' Sensasi dari otot, sendi, dan keseimbangan saat bergerak yang membantu merasakan kestabilan atau kekuatan tolakan merupakan sumber umpan balik....', NULL, ' visual', NULL, 'auditori', NULL, 'kinestetik', NULL, 'isyarat', NULL, 'internal', NULL, 'C'),
(3204, 74, 34, 0, '7A', 'Bentuk komunikasi nonverbal berupa gerakan tubuh, ekspresi wajah, atau sinyal tangan yang penting dalam permainan tim disebut umpan balik....', NULL, 'auditori', NULL, 'isyarat', NULL, 'kinestetik', NULL, 'hasil', NULL, 'visual', NULL, 'B'),
(3205, 74, 34, 0, '7A', 'Seorang pemain sepak bola yang melihat bola\r\ntendangannya melambung jauh melewati mistar gawang, kemudian menyadari kesalahan dalam sudut tendangannya, terutama menggunakan umpan balik....\r\n', NULL, 'kinestetik dan hasil', NULL, 'isyarat dan kinestetik', NULL, 'auditori dan isyarat', NULL, 'visual dan hasil', NULL, 'visual dan hasil', NULL, 'D'),
(3206, 74, 34, 0, '7A', 'Kemampuan menggabungkan penglihatan dengan gerakan tangan untuk melakukan aktivitas seperti menangkap bola atau memukul dengan raket secara tepat adalah komponen ....', NULL, 'koordinasi mata dan tangan', NULL, 'kelincahan', NULL, 'akurasi', NULL, 'persepsi ruang', NULL, ' kekuatan', NULL, 'A'),
(3207, 74, 34, 0, '7A', '.  Ketepatan dalam mengarahkan suatu gerakan\r\nsesuai dengan sasaran yang dituju, seperti menendang bola ke gawang atau melakukan servis tenis meja, merupakan komponen keterampilan gerak yang disebut....\r\n', NULL, 'komunikasi ', NULL, 'akurasi', NULL, 'reaksi cepat', NULL, 'persepsi ruang', NULL, 'kekuatan', NULL, 'B'),
(3208, 74, 34, 0, '7A', 'Kemampuan menyampaikan dan menerima informasi melalui gerakan, isyarat, atau instruksi selama aktivitas fisik, yang menjadi kunci keberhasilan dalam olahraga beregu, adalah komponen .... ', NULL, 'akurasi', NULL, 'persepsi ruang', NULL, 'kelincahan', NULL, 'komunikasi', NULL, 'kekuatan', NULL, 'D'),
(3209, 74, 34, 0, '7A', 'Perhatikan pernyataan berikut!\r\n(1) Demonstrasi bertujuan untuk memberikan\r\ncontoh gerakan yang jelas-kepada kalian.\r\n(2) Penjelasan membantu kalian memahami\r\nalasan di balik teknik gerakan.\r\n(3) Latihan dilakukan hanya satu kali untuk\r\nmemastikan keterampilan dikuasai.\r\n(4) Progresi melibatkan peningkatan tingkat\r\nkesulitan keterampilan.\r\nPernyataan yang sesuai dengan tahap-tahap\r\ndalam akuisisi keterampilan gerak ditunjukkan\r\noleh nomor....\r\n', NULL, '(1), (2), dan (3)', NULL, '(2), (3), dan (4)', NULL, '(1), (2), dan (4)', NULL, '(1), (2), dan (3)', NULL, ' (1), (3), dan (4)', NULL, 'B'),
(3210, 74, 34, 0, '7A', '.  Perhatikan pernyataan berikut!\r\n(1) Komunikasi dalam olahraga beregu hanya\r\nterjadi antara pemain dan pelatih.\r\n(2) Akurasi penting dalam olahraga dengan target.\r\n(3) Latihan monoton dapat menyebabkan\r\nkelelahan tanpa kemajuan.\r\n(4) Kelincahan tidak diperlukan dalam\r\nolahraga yang mengharuskan perubahan\r\narah cepat.\r\nPernyataan yang paling tepat tentang prinsip\r\ndalam melatih keterampilan gerak ditunjukkan oleh nomor\r\n', NULL, '(1), (2), dan (3)', NULL, ' (2), (3), dan (4)', NULL, '(1), (2), dan (4)', NULL, '(2), (3), dan (4)', NULL, '(1), (3), dan (4)', NULL, 'C'),
(3211, 74, 34, 0, '7A', 'Siasat atau cara yang digunakan pemain atau tim untuk mencapai tujuan permainan secara sportif, yang sangat bergantung pada kecerdasan membaca situasi dan mengambil keputusan ...', NULL, ' strategi', NULL, 'taktik', NULL, ' teknik', NULL, 'formasi', NULL, 'reaksi', NULL, 'B'),
(3212, 74, 34, 0, '7A', 'Rencana umum yang disusun sebelum pertandingan dan bersifat jangka panjang, seperti memilih formasi atau pola serangan.\r\nutama, disebut ....\r\n', NULL, 'taktik', NULL, ' strategi', NULL, 'manuver', NULL, 'aplikasi', NULL, 'formasi', NULL, 'B'),
(3213, 74, 34, 0, '7A', 'Pergerakan aktif mencari ruang kosong untuk membuka jalur umpan dalam permainan lempar tangkap bola termasuk penerapan taktik ....', NULL, 'pertahanan', NULL, 'mengelabui lawan', NULL, 'pergerakan tanpa bola', NULL, 'lemparan tepat sasaran', NULL, 'kelincahan', NULL, 'C'),
(3214, 74, 34, 0, '7A', 'Kemampuan untuk mengetahui dan memanfaatkan area lapangan sesuai dengan situasi permainan, menentukan posisi aman, dan membuka peluang bagi kerja sama tim disebut ....', NULL, 'keterampilan teknik dasar', NULL, 'kecepatan reaksi', NULL, 'daya tahan fisik', NULL, 'pemahaman ruang', NULL, 'keterampilan reaksi', NULL, 'D'),
