(4195, 28, 6, 0, '9B', 'Ilmu yang bermanfaat menurut ajaran Islam adalah ilmu yang ....', NULL, 'Digunakan untuk mencari kekayaan dunia', NULL, 'Membuat orang menjadi sombong', NULL, 'Dapat mendekatkan diri kepada Allah', NULL, 'Dapat menguasai orang lain', NULL, '', NULL, 'C'),
(4196, 28, 6, 0, '9B', 'Rasulullah SAW bersabda: â€œMenuntut ilmu itu wajib bagi setiap muslim.â€ (HR. Ibnu Majah).Hadis tersebut menunjukkan bahwa ....', NULL, 'Ilmu hanya wajib bagi laki-laki', NULL, 'Menuntut ilmu tidak penting', NULL, 'Hanya orang kaya yang boleh belajar', NULL, '. Setiap muslim wajib menuntut ilmu', NULL, '', NULL, 'D'),
