(4199, 28, 6, 0, '9B', 'Salah satu tanda seseorang memiliki semangat keilmuan adalah ....', NULL, 'Cepat puas dengan pengetahuan yang dimiliki', NULL, 'Selalu ingin belajar dan mencari kebenaran', NULL, 'Tidak mau mendengar pendapat orang lain', NULL, 'Sering merendahkan orang bodoh', NULL, '', NULL, 'B'),
(4200, 28, 6, 0, '9B', 'Dalam Al-Qurâ€™an surat Al-Mujadilah ayat 11 disebutkan bahwa Allah akan meninggikan derajat orang yang ....', NULL, 'Banyak harta dan kekuasaan', NULL, 'Rajin beribadah dan berilmu', NULL, 'Punya kedudukan tinggi', NULL, 'Banyak teman dan pengikut', NULL, '', NULL, 'B'),
