(4202, 28, 6, 0, '9B', 'Nabi Muhammad SAW sangat menghargai ilmu. Hal ini dibuktikan dengan ....', NULL, 'Menjadikan tawanan perang sebagai guru baca-tulis', NULL, 'Menolak belajar dari orang lain', NULL, 'Melarang umatnya membaca', NULL, 'Mengajarkan ilmu hanya pada keluarganya', NULL, '', NULL, 'A'),
(4203, 28, 6, 0, '9B', 'Sikap terbaik terhadap guru ketika belajar adalah ....', NULL, 'Menyimak dengan sungguh-sungguh', NULL, 'Bermain ponsel saat pelajaran', NULL, 'Menyela penjelasan guru', NULL, 'Tidak memperhatikan', NULL, '', NULL, 'A'),
