(4205, 28, 6, 0, '9B', 'Salah satu manfaat ilmu adalah ....', NULL, 'Membuat manusia jauh dari Allah', NULL, 'Menumbuhkan kesombongan', NULL, 'Membawa kebaikan bagi diri dan orang lain', NULL, 'Menghambat kemajuan masyarakat', NULL, '', NULL, 'C'),
(4206, 28, 6, 0, '9B', 'Contoh penerapan semangat keilmuan di sekolah adalah ....', NULL, 'Belajar hanya saat ujian', NULL, 'Rajin membaca di perpustakaan', NULL, 'Mengabaikan tugas guru', NULL, '. Menunda pekerjaan rumah', NULL, '', NULL, 'B'),
(4207, 28, 6, 0, '9B', 'Orang yang berilmu tetapi sombong terhadap orang lain termasuk orang yang ....', NULL, 'Berilmu sejati', NULL, 'Rendah hati', NULL, 'Tidak mendapat berkah ilmu', NULL, 'Dihormati Allah', NULL, '', NULL, 'C'),
