(4303, 28, 5, 0, '8B', 'Lam jalalah dibaca tafkim apabila ...', NULL, 'apabila ada huruf ber harakat kasrah atau harakat sukun', NULL, 'apabila ada huruf ber harakat fathah atau harakat damah', NULL, 'berada sebelum harakat fathah atau sebelum harakat damah', NULL, 'berada setelah harakat fathah atau setelah harakat damah', NULL, '', NULL, 'B'),
