(4306, 28, 5, 0, '8B', 'Meyakini keberadaan kitab-kitab Allah merupakan perkara yang sangat penting bagi umat Islam. Sebagai orang yang beriman kepada kitab Allah berarti kita harus....', NULL, 'mempercayai dan mengamalkan semua isi kitab Allah Swt', NULL, 'percaya bahwa kitab-kitab itu betul-betul dari Allah Swt.', NULL, 'percaya dan mengamalkan semua kitab-kitab yang ada', NULL, 'menganggap bahwa al-Qurâ€™Än saja yang perlu dipercayai', NULL, '', NULL, 'B'),
(4307, 28, 5, 0, '8B', 'Allah Swt, menurunkan kitab-kitab kepada para rasul-Nya untuk disampaikan kepada umat manusia dengan tujuan â€¦', NULL, 'Dijadikan petunjuk hidup manusia', NULL, 'Dibaca oleh umat manusia', NULL, 'Dimiliki oleh umat manusia', NULL, 'Diambil sebagian sebagai contoh', NULL, '', NULL, 'A'),
(4308, 28, 5, 0, '8B', 'Perhatikan pernyataan berikut! 1) Membaca merupakan ibadah      2) menyempurnakan kitab-kitab sebelumnya 3) berlaku hanya untuk umat tertentu 4) bahasanya tidak semua orang bisa mengerti 5) dijamin keasliannya sampai hari kiamat      6) isinya mencakup semua aspek kehidupan Yang termasuk keistimewaan Alquran dibandingkan dengan kitab-kitab yang lain, adalahâ€¦', NULL, '1,2,3 dan 4', NULL, '2,3,4 dan 5', NULL, '1,2,5 dan 6', NULL, '1,2,4 dan 6', NULL, '', NULL, 'C'),
(4309, 28, 5, 0, '8B', 'Secara istilah, iman berarti membenarkan dengan hati, mengikrarkan dengan lisan, dan membuktikan dengan â€¦', NULL, 'Doa', NULL, 'Semangat', NULL, 'Perbuatan', NULL, 'Keyakinan', NULL, '', NULL, 'C'),
(4310, 28, 5, 0, '8B', 'Fulan mengatakan bahwa ia beriman kepada Al Qurâ€™an. Ia juga mampu membaca Al Qurâ€™an dan mengetahui bahwa babi merupakan binatang yang haram dimakan, tetapi ia juga memakannya. Berdasarkan kisah tersebut dapat dikatakan bahwa Fulan merupakan seorang yang â€¦', NULL, 'Iman kepada Al Qurâ€™an', NULL, 'Sedikit Iman', NULL, 'Tidak Beiman kepada Al-Qur\'an', NULL, 'Zuhud', NULL, '', NULL, 'C'),
(4311, 28, 5, 0, '8B', 'Perhatikan pernyataan berikut! 1)	Sebagai penyempurna kitab terdahulu 2)	Diturunkan dalam waktu sebulan 3)	Berisi tentang hikmah dan puji pujian saja 4)	Berlaku bagi seluruh umat 5)	Petunjuk bagi orang-orang yang bertakwa. Pernyataan yang berhubungan dengan Al Qurâ€™an ditunjukkan oleh nomor â€¦', NULL, '1,2 dan 3', NULL, '1,3 dan 4', NULL, '1,4 dan 5', NULL, '1,2 dan 5', NULL, '', NULL, 'C'),
(4312, 28, 5, 0, '8B', 'Kitab yang memberitahukan bahwa akan muncul seorang nabi, yang mempunyai sifat-sifat mulia, syariatnya lebih sempurna dan bersifat universal (menyeluruh) tidak terbatas oleh waktu dan tempat. Dia adalah nabi penutup dan rasul terakhir yaitu Nabi Muhammad SAW. Kitab tersebut adalah â€¦', NULL, 'Injil', NULL, 'Zabur', NULL, 'Taurat', NULL, 'Suhuf', NULL, '', NULL, 'A'),
(4313, 28, 5, 0, '8B', 'Pengertian suhuf Adalah â€¦', NULL, 'Wahyu Allah yang diterima nabi dan dibukukan', NULL, 'Ucapan para nabi yang sudah tertulis dan dibukukan', NULL, 'Ketetapan para sahabat nabi yang telah dibukukan', NULL, 'Lembaran wahyu Allah yang tidak dibukukan', NULL, '', NULL, 'D'),
(4314, 28, 5, 0, '8B', 'Menerapkan perintah Allah dalam Al Qurâ€™an merupakan sebuah ciri dari orang yang â€¦.', NULL, 'Bermartabat di Masyarakat', NULL, 'Kurang berpendirian', NULL, 'Tidak memiliki mimpi', NULL, 'Beriman dan bertaqwa kepada Allah', NULL, '', NULL, 'D'),
(4315, 28, 5, 0, '8B', 'Al-Qurâ€™an turun kepada Nabi Muhammad dengan membawa â€¦.', NULL, 'Rezeki', NULL, 'Kebenaran', NULL, 'Kesuksesan', NULL, 'Larangan', NULL, '', NULL, 'B'),
