(4319, 28, 5, 0, '8B', 'Al Qurâ€™an diturunkan secara berangsur angsur, Surat yang pertama kali turun Adalah â€¦', NULL, 'Al-Fatihah:1-3', NULL, 'Al-Baqarah:1-5', NULL, 'Al-Alaq:1-5', NULL, 'Al-Maidah:1-5', NULL, '', NULL, 'C'),
