(4321, 28, 5, 0, '8B', 'Diantara Nabi berikut yang menerima suhuf Adalah Nabi â€¦', NULL, 'Harun a.s.', NULL, 'Ibrahim a.s.', NULL, 'Ismail a.s.', NULL, 'Sulaiman a.s.', NULL, '', NULL, 'B'),
(4322, 28, 5, 0, '8B', 'Tempat turunnya wahyu Al Qurâ€™an yang pertama di â€¦', NULL, 'Gua Hira', NULL, 'Jabal Rahmah', NULL, 'Bukit Tursina', NULL, 'Jabal Uhud', NULL, '', NULL, 'A'),
(4323, 28, 5, 0, '8B', 'Seorang rasul tidak mungkin bersifat bodoh. Jika seorang rasul bersifat bodoh, pasti akan diatur dan dipermainkan oleh umatnya. Maka seorang rasul mustahil memiliki sifat â€¦', NULL, 'Kizib', NULL, 'Khianat', NULL, 'Kitman', NULL, 'Baladah', NULL, '', NULL, 'D'),
(4324, 28, 5, 0, '8B', 'Berikut yang termasuk sifat wajib bagi rasul adalah â€¦', NULL, 'Kitman', NULL, 'Baladah', NULL, 'Sidiq', NULL, 'Kizib', NULL, '', NULL, 'C'),
(4325, 28, 5, 0, '8B', 'Peilaku seorang pelajar yang mencerminkan beriman kepada para Rasul Ketika sedang ujian Adalah â€¦.', NULL, 'Mencontek dari buku', NULL, 'Menjawab sesuai dengan kemampuan sendiri', NULL, 'Pasrah saja karena yakin tidak mampu menjawab', NULL, 'Menunggu jawaban dari teman', NULL, '', NULL, 'B'),
(4326, 28, 5, 0, '8B', 'Perhatikan ilustrasi berikut! Ibu guru menitip pesan kepada ketua kelas untuk menyampaikan kepada teman-teman untuk mengumpulkan PR esok hari, tetapi ketua kelas tidak menyampaikannya. Sikap yang menunjukkan ketua kelas di atas Adalah cerminan salah satu sifat mustahil rasul dalam kehidupan sehari-hari yaitu sifat â€¦.', NULL, 'Kizib', NULL, 'Khianat', NULL, 'Kitman', NULL, 'Baladah', NULL, '', NULL, 'B'),
(4327, 28, 5, 0, '8B', 'Seorang rasul sangat dapat dipercaya oleh umatnya. Para Rasul Adalah manusia yang jujur dan dapat dipercaya. Hal ini berarti rasul mempunyai sifat â€¦.', NULL, 'Baladah', NULL, 'Amanah', NULL, 'Tabligh', NULL, 'Fatanah', NULL, '', NULL, 'B'),
(4328, 28, 5, 0, '8B', 'Di bawah ini yang merupakan contoh perilaku meniru sunah harian Rasulullah yang sangat mudah dipraktikkan oleh murid di rumah adalah â€¦', NULL, 'Mengadakan perjalanan jauh lintas negara tiap bulan', NULL, 'Makan dan minum menggunakan tangan kanan sambil duduk', NULL, 'Tidur larut malam untuk bermain game', NULL, 'Berbicara udengan suara yang sangat keras kepada orang tua', NULL, '', NULL, 'B'),
(4329, 28, 5, 0, '8B', 'Masa depan seorang remaja yang menjadikan Rasulullah sebagai figure teladan utama dalam hidupnya akan cenderung â€¦.', NULL, 'Kehilangana arah karena ajarann nabi dianggap kuno', NULL, 'Terjaga dari pengaruh buruk perkembangan zaman', NULL, 'Dijauhi oleh teman-teman karena terlalu taat', NULL, 'Sulit mendapatkan popularitas di kalangan teman-teman mengaji', NULL, '', NULL, 'B'),
(4360, 30, 7, 0, '8B', 'Berikut ini merupakn defenisi dari teks laporan hasil observasi adalahâ€¦.', NULL, 'Teks yang berfungsi untuk memberikan informasi mengenai suatu objek atau situasi, setelah diadakannya investigasi atau penelitian secara sistematis.', NULL, 'Teks yang berfungsi untuk menyamakan  informasi mengenai suatu objek atau situasi, setelah diadakannya investigasi atau penelitian secara sistematis.', NULL, 'Teks yang berfungsi untuk memberikan informasi mengenai suatu objek atau situasi, tanpa adanya investigasi atau penelitian secara sistematis.', NULL, 'Teks yang berfungsi untuk memberikan informasi mengenai suatu objek atau situasi, setelah diadakannya investigasi atau penelitian tanpa adanya sebuang  dasar yang jelas.', NULL, '', NULL, 'A'),
(4361, 30, 7, 0, '8B', 'Berikut ini adalah sifat- sifat teks observasi, kecualiâ€¦.', NULL, 'Bersifat faktual', NULL, 'Bersifat aktual', NULL, 'Bukan berupa argument', NULL, 'Bukan berupa kemungkinan', NULL, '', NULL, 'B'),
(4362, 30, 7, 0, '8B', 'Berikut ini termasuk ciri-ciri dari teks laporan hasil observasi, kecuali....', NULL, 'Bersifat objektif', NULL, 'Mengandung pendapat tokoh ahli', NULL, 'Harus ditulis sempurna dan lengkap', NULL, 'Tidak memasukkan hal-hal yang menyimpangm mengandung prasangka, atau pemihakan', NULL, '', NULL, 'B'),
(4363, 30, 7, 0, '8B', 'Menyampaikan informasi tentang sesuatu, apa adanya sebagai hasil pengamatan sistematis atau analisis. Pernyataan tersebut merupakan tujuan dari....', NULL, 'Teks eksposisi', NULL, 'laporan hasil observasi', NULL, 'bagian  dari teks laporan', NULL, 'isi teks deskripsi', NULL, '', NULL, 'B'),
(4364, 30, 7, 0, '8B', 'Penelitian hasil observasi Laporan hasil observasi harus disajikan dengan menggunakan bahasa yang jelas, mudah dipahami, dan tidak berbelit-belit. Hal ini dilakukan untuk menghindari....', NULL, 'kesalahpahaman pembaca', NULL, 'keterlibatan tokoh masyarakat', NULL, 'kesalahan penulisan', NULL, 'salah menguraikan pendapat/opini', NULL, '', NULL, 'A'),
(4365, 30, 7, 0, '8B', 'Objek yang diamati dalam pembuatan teks laporan hasil observasi haruslah.....', NULL, 'objek', NULL, 'objek tunggal', NULL, 'subjek', NULL, 'objek ganda', NULL, '', NULL, 'B'),
(4366, 30, 7, 0, '8B', 'Kalimat utama paragraf berikut ini adalahâ€¦               Kunang-kunang merupakan jenis serangga yang sangat unik karena mampu mengeluarkan cahaya dari tubuhnya. Cahaya alami ini dihasilkan oleh organ khusus di bawah perut mereka melalui proses kimia yang disebut bioluminesensi. Umumnya, kunang-kunang menggunakan kelap-kelip cahaya tersebut untuk saling berkomunikasi dan menarik perhatian pasangan saat musim kawin. Di dunia ini, terdapat lebih dari dua ribu spesies kunang-kunang yang sebagian besar dapat ditemukan di daerah beriklim tropis dan hangat.', NULL, 'Kunang- kunang merupakan jenis serangga yang unik.', NULL, 'Kunang â€“ kunang serangga yang mampu mengeluarkan Cahaya.', NULL, 'Kunang-kunang merupakan jenis serangga yang sangat unik karena mampu mengeluarkan cahaya dari tubuhnya.', NULL, 'Kunang-kunang yang sebagian besar dapat ditemukan di daerah beriklim tropis dan hangat.', NULL, '', NULL, 'C'),
(4367, 30, 7, 0, '8B', 'Kalimat utama paragraf berikut adalahâ€¦ Ada dua pilihan tiket sebagai biaya masuk Bukit Mongkrang. Untuk pengun-jung yang datang sekaligus ingin berke-mah akan dikenakan tiket masuk sebesar Rp15.000,00. Adapun pengunjung yang tidak berkemah akan dikenakan tiket masuk sebesar Rp 10.000,00. Tiket dapat dibeli di loket. Pendaki dapat bertanya mengenai seluk-beluk pendakian Bukit Mongkrang kepada pemandu di loket.', NULL, 'Seluk beluk pendakian Bukit Mongrang kepada Pemandu di loket.', NULL, 'Tiket dapat dibeli.', NULL, 'Pengunjung yang tidak berkemah akan dikenakan tiket masuk sebesar Rp 10.000,00.', NULL, 'Ada dua pilihan tiket sebagai biaya masuk Bukit Mongkrang.', NULL, '', NULL, 'D'),
(4368, 30, 7, 0, '8B', 'Bacalah dengan cermat! (1) Lidah buaya merupakan tanaman yang bisa tumbuh di berapa tempat dan suhu. (2) Lidah buaya biasanya tumbuh di tempat yang memiliki suhu panas. (2)Tanaman berduri ini juga biasa di tanam di dalam pot maupun di pekarangan rumah untuk dijadikan tanaman hias. (3) Beberapa orang juga menggunakannya untuk mempercepat penyembuhan luka dan perawatan rambut.  Gagasan utama paragraf di atas adalahâ€¦.', NULL, 'Lidah buaya biasanya tumbuh di tempat yang memiliki suhu panas.', NULL, 'Lidah buaya tumbuh di banyak tempat dan suhu', NULL, 'Beberapa orang juga menggunakannya untuk mempercepat penyembuhan luka dan perawatan rambut.', NULL, 'Lidah uaya memiliki banyak manfaat.', NULL, '', NULL, 'B'),
(4369, 30, 7, 0, '8B', 'Bacalah dengan teliti potongan paragraf berikut ini!          Upacara bendera memperingati HUT RI ke-79 berlangsung dengan khidmat. Semua peserta tampak antusias mengikuti kegiatan. Pembina upacara menyampaikan pidato yang sangat menginspirasi, terutama bagian yang menyoroti pentingnya persatuan dan kesatuan bangsa. Lagu-lagu nasional yang dinyanyikan bersama-sama menambah semarak suasana. Namun, cuaca yang sedikit mendung sempat mengkhawatirkan, untungnya hujan tidak turun. Kalimat data berdasar potongan teks tersebut adalahâ€¦.', NULL, 'Upacara bendera memperingati HUT RI ke-79 berlangsung dengan khidmat.', NULL, 'Namun, cuaca yang sedikit mendung sempat mengkhawatirkan, untungnya hujan tidak turun.', NULL, 'Pembina upacara menyampaikan pidato yang sangat menginspirasi.', NULL, 'Semua peserta tampak sangat berbahagia mengikuti kegiatan.', NULL, '', NULL, 'A'),
(4370, 30, 7, 0, '8B', 'Kalimat data ditunjukkan oleh nomorâ€¦.Bulan Bahasa dan Sastra merupakan momen penting untuk memperingati hari lahirnya Sumpah Pemuda. (2) Kegiatan ini diselenggarakan setiap tahun sebagai bentuk penghormatan terhadap bahasa Indonesia sebagai bahasa persatuan. (3) Berdasarkan sejarahnya, Bulan Bahasa rutin diperingati setiap bulan Oktober sejak ditetapkan oleh Badan Pengembangan dan Pembinaan Bahasa pada tahun 1980. (4) Melalui berbagai lomba dan seminar yang diadakan, generasi muda diharapkan dapat terus menjaga serta mencintai identitas nasionalnya.', NULL, '1', NULL, '2', NULL, '3', NULL, '4', NULL, '', NULL, 'C'),
(4371, 30, 7, 0, '8B', 'Berikut ini merupakan kalimat fakta adalahâ€¦', NULL, 'Taman Nasional Baluran memiliki berbagai macam flora dan fauna serta ekosistem.', NULL, 'Tumbuhan di taman nasional ini sebanyak 444 jenis.', NULL, 'Di taman ini juga terdapat 26 jenis mamalia.', NULL, 'Mungkin di taman Nasional Baluran juga terdapat tanaman- tanaman yang bisa tumbuh di sekitar kita.', NULL, '', NULL, 'A'),
(4372, 30, 7, 0, '8B', 'Kalimat fakta yang tepat ditunjukkan olehâ€¦', NULL, 'Selain itu, terdapat sekitar 155 jenis burung, di antaranya termasuk yang langka seperti layang-layang api (Hirundo rustica).', NULL, 'Widoro bukol, mimba, dan pilang merupakan tumbuhan yang mampu beradaptasi dalam kondisi yang sangat kering (masih kelihatan hijau), walaupun tumbuhan lainnya sudah layu dan mengering.', NULL, 'Tanaman widoro salah satu tanaman yang membuat sejuk dan rindang jika ditanam di dekat rumah.', NULL, 'Seandainya Taman nasional Baluran berada disekitar wilayah kita, kita akan lebih mudah menyaksikan berbagai flora dan fauna.', NULL, '', NULL, 'B'),
(4373, 30, 7, 0, '8B', 'Berikut ini adalah kalimat data yang tepat..', NULL, 'Sebanyak 500 siswa dan guru mengikuti upacara peringatan ulang tahun kemerdekaan RI.', NULL, 'Pakaian adat dari berbagai daerah menghiasi barisan peserta upacara.', NULL, 'Pasukan pengibar bendera berhasil menjalankan tugasnya dengan sempurna.', NULL, 'Peringatan HUT RI tahun ini juga dimeriahkan dengan pameran hasil karya siswa.', NULL, '', NULL, 'A'),
(4374, 30, 7, 0, '8B', 'Bacalah teks berikut dengan seksama!Upacara bendera memperingati HUT RI ke-79 berlangsung dengan khidmat. Semua peserta tampak antusias mengikuti kegiatan. Pembina upacara menyampaikan pidato yang sangat menginspirasi, terutama bagian yang menyoroti pentingnya persatuan dan kesatuan bangsa. Lagu-lagu nasional yang dinyanyikan bersama-sama menambah semarak suasana. Namun, cuaca yang sedikit mendung sempat mengkhawatirkan, untungnya hujan tidak turun.               Kalimat objektif dalam paragraf di atas adalahâ€¦', NULL, 'Upacara bendera memperingati HUT RI ke-79 berlangsung dengan khidmat.', NULL, 'Namun, cuaca yang sedikit mendung sempat mengkhawatirkan, untungnya hujan tidak turun.', NULL, 'Pembina upacara menyampaikan pidato yang sangat menginspirasi.', NULL, 'Semua peserta tampak sangat berbahagia mengikuti kegiatan', NULL, '', NULL, 'A'),
(4375, 30, 7, 0, '8B', 'Berikut ini merupakn kalimat subjektif yang tepat adalahâ€¦', NULL, 'Diskusi kelompok tadi terasa sangat menyenangkan dan membuat waktu berjalan begitu cepat.\"', NULL, 'pukul 07.00 WIB bus kota nomor 17 melaju di sepanjang Jalan Jenderal Sudirman.', NULL, 'Ia mengenakan kemeja berwarna biru.', NULL, 'Pembina upacara menyampaikan pidato tentang tata tertib sekolah.', NULL, '', NULL, 'A'),
(4376, 30, 7, 0, '8B', 'Perhatikan potongan teks laporan hasil observasi berikut ini!           (1) Hutan mangrove adalah ekosistem unik yang terletak di pesisir tropis dan subtropis, tepatnya di antara daratan bertemu dengan laut. (2) Hutan ini dikenal dengan keanekaragaman spesies tumbuhan dan hewan yang hidup di dalamnya, serta fungsinya untuk melindungi garis pantai dari erosi. (3) Desa Teluk Naga memiliki hutan mangrove yang penting bagi komunitas local secara ekologis dan ekonomi. Berdarkan potongan paragraf di atas, kalimat nomor berapakah yang merupakan kalimat fakta?', NULL, '(1), (2)', NULL, '(2),(3)', NULL, '(1), (2),', NULL, '2', NULL, '', NULL, 'D'),
(4377, 30, 7, 0, '8B', 'Berikut ini merupakan struktur teks laporan observasiâ€¦.', NULL, 'Abstraksi, orientasi, Krisis, reaksi, dan koda', NULL, 'Pernyataan pendapat, argumentasi, dan penegaan ulang', NULL, 'Definisi umum, deskripsi bagian,dan  simpulan', NULL, 'Pernyataan definisi dan pernyataan umum.', NULL, '', NULL, 'C'),
(4378, 30, 7, 0, '8B', 'Berikut ini adalah bagian definisi umum dalam teks laporan hasil observasiâ€¦', NULL, 'Taman sekolah kami merupakan paru-paru sekolah yang asri. Taman ini terletak di tengah-tengah area sekolah, dikelilingi oleh bangunan kelas dan lapangan olahraga. Di tengah taman terdapat sebuah kolam ikan yang dipenuhi oleh berbagai jenis ikan hias. Beberapa pohon besar seperti mangga dan jambu biji tumbuh rindang di sudut-sudut taman. Selain itu, terdapat juga berbagai jenis tanaman hias yang ditanam dalam pot-pot cantik. Taman sekolah ini menjadi tempat yang nyaman bagi siswa untuk bersantai dan belajar di alam terbuka.', NULL, 'Sungai yang mengalir di belakang sekolah kami terlihat kurang terawat. Air sungai terlihat keruh dan banyak sampah berserakan di pinggirannya. Beberapa jenis tumbuhan air liar tumbuh subur menutupi permukaan sungai. Terkadang, kami melihat beberapa siswa membuang sampah sembarangan ke sungai. Kondisi sungai ini sangat memprihatinkan karena dapat mencemari lingkungan dan mengganggu ekosistem yang ada di dalamnya.', NULL, 'Di lingkungan rumah saya, sebagian besar warga masih membuang sampah sembarangan. Mereka sering membuang sampah plastik, sisa makanan, dan sampah organik lainnya ke selokan atau sungai. Tempat pembuangan sampah umum yang disediakan oleh pemerintah seringkali penuh dan tidak dikelola dengan baik. Akibatnya, lingkungan menjadi kotor dan menimbulkan bau tidak sedap. Perlu adanya kesadaran yang lebih tinggi dari warga untuk membuang sampah pada tempatnya dan memilah sampah dari sumbernya.', NULL, 'Akhir-akhir ini demonstrasi kerap terjadi hampir setiap waktu dan terjadi di berbagai tempat. Bahkan, demonstrasi sudah menjadi fenomena yang lumrah di tengah-tengah masyarakat kita. Menanggapi fenomena tersebut, seorang kepala daerah menyatakan bahwa penyebab demonstrasi dan anarkisme tidak lain adalah faktor laparnya masyarakat. Lantas ia mencontohkan rakyat Malaysia dan Brunei yang adem ayem, lantaran kesejahteraan mereka terpenuhi maka demonstrasi di negara-negara itu jarang terjadi.', NULL, '', NULL, 'D'),
(4379, 30, 7, 0, '8B', 'Yang bukan teks observasi adalahâ€¦', NULL, 'Bencana alam adalah suat u peristiwa alam yang mengakibatkan dampak besar bagi populasi manusia.', NULL, 'Bencana alam dapat terjadi di mana pun dan kapan pun, tak terkecuali di Indonesia.', NULL, 'Indonesia merupakan negara kepulauan yang rawan bencana alam.', NULL, 'Bencana alam di Indonesia seperti gempa bumi, gunung meletus, banjir, dan tanah longsor.', NULL, '', NULL, 'A'),
(4380, 30, 7, 0, '8B', 'Bacalah teks berikut dengan cermat!Bencana alam adalah suatu peristiwa alam yang mengakibatkan dampak besar bagi populasi manusia. Bencana alam dapat terjadi dinana pun dan kapan pun, tak terkecuali di Indonesia. Indonesia merupakan negara kepulauan yang rawan bencana alam. Itulah sebabnya Indonesia banyak mengalami bencana alam terutama gempa bumi, gunung meletus, banjir, dan tanah longsor. Potongan paragraf di atas merupakan struktur teks laporan observasi bagianâ€¦', NULL, 'Defenisi', NULL, 'Deskripsi  bagian', NULL, 'Simpulan', NULL, 'Isi', NULL, '', NULL, 'A'),
(4381, 30, 7, 0, '8B', 'Penggunaan tada baca koma yang tepat terdapat pada kalimat berikut ini!', NULL, 'Aku sudah sampai di kota tetapi uang sakuku tertinggal di rumah.', NULL, 'Karena baik hati dia memiliki banyak teman.', NULL, 'O, anak yang berbaju merah itu yang menjadi juara di lomba kemarin?', NULL, 'Meskipun mahal aku tetap membeli sepeda Listrik itu.', NULL, '', NULL, 'C'),
(4382, 30, 7, 0, '8B', 'Perhatikan kutipan teks laporan hasil observasi berikut ini! Fungsi museum yang utama adalah menyimpan, merawat, mengamankan, dan memanfaatkan koleksi museum berupa benda cagar budaya. Dengan demikian, museum memiliki fungsi besar yaitu sebagai tempat pelestarian.Objek yang sedang dibahas dalam teks di atas adalah ...', NULL, 'fungsi museum', NULL, 'tempat museum', NULL, 'wisata museum', NULL, 'museum', NULL, '', NULL, 'A'),
(4383, 30, 7, 0, '8B', 'Bacalah teks berikut daengan seksama!(1) Museum merupakan salah satu tempat paling penting dalam upaya pelestarian Sejarah. (2) Museum adalah lembaga yang berfungsi mengumpulkan, merawat, dan menyajikan serta melestarikan warisan budaya masyarakat untuk tujuan studi, penelitian, dan kesenangan atau hiburan. (3) Fungsi museum yang utama adalah menyimpan, merawat, mengamankan, dan memanfaatkan koleksi museum berupa benda cagar budaya. (4) Dengan demikian, museum memiliki fungsi besar yaitu sebagai tempat pelestarian. Kalimat definisi dalam paragraf di atas adalah, kecualiâ€¦', NULL, '1', NULL, '2', NULL, '3', NULL, '4', NULL, '', NULL, 'D'),
(4384, 30, 7, 0, '8B', 'Bacalah dengan seksama! Lingkungan hidup adalah segala sesuatu yang ada di sekitar manusia dan berhubungan timbal balik. Lingkungan hidup ini mencakupi benda hidup dan benda mati. Benda hidup perlu makanan dan berkembang biak seperti manusia, binatang, dan tumbuhan. Benda mati antara lain tanah, air, api, batu, dan udara. Jika terpelihara dengan baik, lingkungan hidup itu dapatmenciptakan masyarakat yang sehat, aman, tenteram, lahir dan batin.Potongan paragraf di atas adalah bagian strukturâ€¦', NULL, 'definisi umum', NULL, 'deskripsi bagian', NULL, 'deskripsi manfaat', NULL, 'penutup', NULL, '', NULL, 'A'),
(4385, 30, 7, 0, '8B', 'Pernyataan berikut yang termasuk deskripsi bagian (isi) dalam strukutr teks laporan observasi adalah ....', NULL, 'Pantai adalah batas antara daratan dengan laut. Batas ini merupakan zona laut sampai dengan kedalaman 200 m (garis isobath 200 m). Jadi, sifat-sifat pantai sama dengan daratan.', NULL, 'Menurut bentuknya ada empat macam pantai, yaitu pantai landai, pantai curam, pantai bertebing, dan pantai karang.', NULL, 'Pantai merupakan tempat wisata yang populer dan pantas untuk dinikmati secara bersama keluarga. Pantai juga memiliki ekosistem pantai yang terdapat komponen biotik dan komponen abiotik. Komponen biotik pantai terdiri atas tumbuhan dan hewan yang hidup di daerah pantai. Sementara komponen abiotik pantai terdiri atas gelombang, arus, angin, pasir, batuan dan sebagainya.', NULL, 'Pantai terdiri atas beberapa jenis. Komponen biotik dan abiotik pantai mengandung banyak manfaat. Selain indah, pantai memiliki manfaat bagi kesehatan, dan nutrisi.', NULL, '', NULL, 'B'),
(4386, 30, 7, 0, '8B', 'Perhatikan kalimat-kalimat acak berikut! 1) Keseimbangan inilah yang harus tetap dijaga agar keanekaragaman sumber daya alam tetap lestari dan terjamin.\n2) Apabila tidak dijaga, keseimbangan alam dapat terganggu atau rusak.\n3) Alam yang serasi dan lestari adalah alam yang mengandung berbagai komponen ekosistem secara seimbang.\n4) Oleh karena itu, pemanfaatan sumber daya alam sebaiknya diusahakan secara arif dan bijaksana. Susunan kalimat yang tepat agar menjadi teks hasil observasi yang padu adalah ....', NULL, '3 â€“ 2 - 1 â€“ 4', NULL, '3 â€“ 1 - 2 â€“ 4', NULL, '3 â€“ 2 â€“ 4 â€“ 1', NULL, '3 â€“ 4 - 1 â€“ 2', NULL, '', NULL, 'B'),
(4387, 30, 7, 0, '8B', 'Perhatikan potongan paragraf berikut ini ! 1). Biota laut Indonesia bermanfaat bagi perkembangan pariwisata, seperti Raja Ampat di Papua, pulau wangi- wanigan di Sulawesi Tenggara, dan Bunaken di Manado.  (2) Keragaman biota laut ini juga bermanfaat bagi lingkungan, terutama bakau yangmenahan erosi dari besarnya hantaman gelombak dan ombak. (3) Meskipun gelombang pasang tidak dtang setiap saat. (4). Mari kita jaga laut kita dari hal- hal yang mengganggu keberlangsungan pelestariannya.                Penggunaaan kata teknis dalam kaliamt di atas ditunjukkan oleh nomorâ€¦.', NULL, '( 1 ) dan  ( 2)', NULL, '(2 ) dan (3)', NULL, '( 3) dan (4)', NULL, '(1) dan (4)', NULL, '', NULL, 'A');
