(4626, 28, 4, 0, '7B', 'Karakteristik iman dalam pandangan akidah Islam bersifat dinamis, yang artinya â€¦.', NULL, 'Nilainya selalu konstan dan tidak akan pernah berubah', NULL, 'Bisa bertambah karena ketaatan dan berkurang karena kemaksiatan', NULL, 'Hanya dimiliki oleh para nabi dan rasul secara mutlak', NULL, 'Otomatis hilang sepenuhnya jika seseorang lupa berdoa', NULL, '', NULL, 'B'),
(4627, 28, 4, 0, '7B', 'Sifat-sifat Allah SWT dan Al Asmaâ€™ al Husna dalam Al Qurâ€™an dan sunah merupakan kesempurnaan mutlak dari sifat-sifat Nya dari segala kekurangan. Al Asmaâ€™ al Husna berartiâ€¦', NULL, 'Sifat-sifat Allah SWT', NULL, 'Nama-nama indah bagi Allah SWT', NULL, 'Nama-nama Rasul yang baik', NULL, 'Sifat-sifat Rasulullah SAW', NULL, '', NULL, 'B'),
(4628, 28, 4, 0, '7B', 'Berikut yang merupakan pengamalan terhadap Asmaul Husna Al â€˜Alim adalah â€¦', NULL, 'Suka membaca buku', NULL, 'Suka memberikan maaf', NULL, 'Dermawan kepada sesama', NULL, 'Menghindari gibah', NULL, '', NULL, 'A'),
(4629, 28, 4, 0, '7B', 'Tidak ada satupun makhluk yang mengetahui datangnya hari kiamat, melainkan Allah SWT sebab Allah SWT memilik Asmaul Husna â€¦', NULL, 'Al Khabir', NULL, 'Al Basir', NULL, 'Al \'Alim', NULL, 'As Sami\'', NULL, '', NULL, 'C'),
(4630, 28, 4, 0, '7B', 'Seseorang yang tidak pernah membicarakan keburukan orang lain termasuk orang yang meyakini bahwa Allah SWT memiliki Asmaul Husna â€¦', NULL, 'As Samiâ€™', NULL, 'Al Bashir', NULL, 'As Salam', NULL, 'Al Quddus', NULL, '', NULL, 'A'),
(4631, 28, 4, 0, '7B', 'Adeva membeli minyak goreng di warung. Adeva menerima kelebihan uang kembalian, kemudian ia mengembalikannya. Adeva sadar bahwa Allah SWT selalu mengawasi setiap gerak geriknya, karena Allah SWT memiliki Asmaul Husna â€¦', NULL, 'As Samiâ€™', NULL, 'Al Basir', NULL, 'Al Khabir', NULL, 'Al â€˜Alim', NULL, '', NULL, 'B'),
(4632, 28, 4, 0, '7B', 'Penglihatan Allah tidak dibatasi oleh ruang yang gelap, dinding yang tebal, maupun jarak. Hal ini karena Allah bersifat â€¦', NULL, 'Al â€˜Alim', NULL, 'Al Khabir', NULL, 'As Samiâ€™', NULL, 'Al Bashir', NULL, '', NULL, 'D'),
