(4634, 28, 4, 0, '7B', 'Alisha selalu berhati-hati dalam berucap karena ia yakin Allah SWT senantiasa mendengarkannya. Perilaku Alisha termasuk pengamalan dari keyakinan bahwa Allah SWT memiliki Asmaul Husna â€¦', NULL, 'Al â€˜Alim', NULL, 'Al Khabir', NULL, 'As Samiâ€™', NULL, 'Al Bashir', NULL, '', NULL, 'C'),
(4635, 28, 4, 0, '7B', 'Berikut perilaku yang merupakan pencerminan keyakinan terhadap Asmaul Husna As Samiâ€™ adalah â€¦', NULL, 'Berusaha mencari pahala sebanyak-banyaknya', NULL, 'Teliti dalam mengerjakan segala sesuatu', NULL, 'Mendengarkan segala nasihat baik dari orang tua', NULL, 'Menyontek saat ulangan', NULL, '', NULL, 'C'),
(4636, 28, 4, 0, '7B', 'Subhanallah alam semesta dengan segala isinya sangat indah. Allah SWT telah menciptakannya dengan rinci. Semuanya sesuai dengan kehendakNya dan bekerja sesuai dengan Sunah Nya. Hal ini membuktikan bahwa Allah SWT â€¦', NULL, 'Maha Mendengar', NULL, 'Maha Melihat', NULL, 'Maha Mengetahui', NULL, 'Maha Teliti', NULL, '', NULL, 'D'),
(4637, 28, 4, 0, '7B', 'Pasya menemukan sebuah dompet dan pasya mengembalikannya kepada pemilik dompet serta mengantarnya sesuai dengan alamat yang ada pada KTP. Ia berkeyakinan bahwa Allah SWT Maha melihat semua perbuatan hamba Nya walaupun tidak ada satupun orang yang melihat tindakan pasya tersebut. Hal tersebut menunjukkan bahwa Pasya meneladani Asmaul Husna â€¦', NULL, 'Al â€˜Alim', NULL, 'Al Basir', NULL, 'As Samiâ€™', NULL, 'Al Khabir', NULL, '', NULL, 'B'),
(4638, 28, 4, 0, '7B', 'Untuk membuktikan kebenaran Allah SWT dapat dipergunakan dalil naqli dan dalil aqli. Dalil Naqli adalah dalil yang berdasarkan â€¦', NULL, 'Pemikiran yang matang', NULL, 'Pendapat cendikiawan', NULL, 'Al Qurâ€™an dan Hadits', NULL, 'Hukum yang berlaku', NULL, '', NULL, 'C'),
(4639, 28, 4, 0, '7B', 'Semua benda dan makhluk di alam semesta ini telah diatur oleh Allah SWT sedemikian rupa dengan fungsi dan kegunaan masing-masing. Hal ini menunjukkan bahwa Allah SWT â€¦', NULL, 'Maha menciptakan', NULL, 'Maha Suci', NULL, 'Maha Mengetahui', NULL, 'Maha Teliti', NULL, '', NULL, 'D'),
(4640, 28, 4, 0, '7B', 'Secara diam-diam bahar menusuk ban sepeda motor milik Umar dengan paku. Memang tidak ada seorangpun yang melihat perbuatan jahat Bahar tersebut, tetapi Allah SWT melihatnya karena Allah SWT mempunyai sifat â€¦', NULL, 'Al Khabir', NULL, 'Al Basir', NULL, 'Al Samiâ€™', NULL, 'Al â€˜Alim', NULL, '', NULL, 'B'),
(4641, 28, 4, 0, '7B', 'Lafal menunjukkan bahwa Allah SWT maha â€¦', 'img_6ad0ddb83e880.png', 'Maha Melihat', NULL, 'Maha Mendengar', NULL, 'Maha Mengetahui', NULL, '', NULL, '', NULL, 'B'),
(4642, 28, 4, 0, '7B', 'Ilmu manusia dibandingkan dengan ilmu Allah SWT ibarat setetes tinta di lautan. Hal ini menunjukkan bahwa ilmu manusia kecil dan sedikit. Oleh karena itu kita tidak boleh sombong dengan ilmu yang dimiliki.Seandainya manusia dapat membuat motor, mobil kapal terbang, satelit rudal dan nuklir sekalipun, semua itu tidak ada apa-apanya dibandingkan dengan ilmu Allah SWT, terkait hal ini Allah SWT mempunyai nama indah â€¦', NULL, 'Al Khabir', NULL, 'Al Basir', NULL, 'Al Samiâ€™', NULL, 'Al â€˜Alim', NULL, '', NULL, 'D'),
(4643, 28, 4, 0, '7B', 'Kita sebagai pelajar muslim diperintahkan untuk berkata baik dan sopan. Asmaul Husna yang sesuai dengan pernyataan tersebut adalah â€¦', NULL, 'Al Alim', NULL, 'Al Basir', NULL, 'As Samiâ€™', NULL, 'Al Khabir', NULL, '', NULL, 'C'),
(4644, 28, 4, 0, '7B', 'Kita diperintahkan untuk berdoa dengan menyebut Asmaâ€™ul Husna, sesuai yang tertuang dalam Quran Surat â€¦.', NULL, 'Al-Aâ€™raf:180', NULL, 'Al-Aâ€™raf:189', NULL, 'Al-Imran:12', NULL, 'Al-Aâ€™raf:179', NULL, '', NULL, 'A'),
(4645, 28, 4, 0, '7B', 'Dibawah ini adalah cerminan beriman kepada Allah melalui Asmaâ€™ul Husna yang diwujudkan dalam kehidupan sehari-hari, kecuali â€¦.', NULL, 'Mewujudkan percaya diri atas ilmu yang diberikan oleh Allah untuk menjelaskan kebenaran', NULL, 'Tekun dalam belajar pada sesuatu yang dianggap baik oleh agama', NULL, 'Teliti dalam belajar dan mengerjakan soal', NULL, 'Mudah menyerah untuk berjuang meraih cita-cita', NULL, '', NULL, 'D'),
(4646, 28, 4, 0, '7B', 'Orang yang beriman kepada Asmaul Husna akan terhindar dari perilaku sombong karena ia menyadari bahwa â€¦.', NULL, 'Manusia tidak memiliki kelemahan apapun', NULL, 'Semua kelebihan yang ia miliki hanyalah titipan Allah', NULL, 'Harta benda akan dibawa sampai mati ke liang kubur', NULL, 'Pujian manusia Adalah tujuan utama dalam hidup', NULL, '', NULL, 'B'),
