(5030, 68, 30, 0, '9A', 'Patrap nyapa aruhi wong kang arep budhal, ukarane ....', NULL, 'Nderek langkung.', NULL, 'Badhe tindak pundi ?', NULL, 'Mangga lenggah pinarak', NULL, 'Nuwun sewu, kulo ngrumiyini', NULL, '', NULL, 'B'),
(5031, 68, 30, 0, '9A', 'Pratelan ing ngisor iki sing ora klebu mungguh gunane basa ngoko lugu yaiku ....', NULL, 'Kanggo guneman kanca marang kanca sabarakan', NULL, 'Kanggo guneman wong tuwo marang anak', NULL, 'Kanggo guneman bendara marang batur', NULL, 'Kanggo guneman murid marang guru', NULL, '', NULL, 'D'),
(5032, 68, 30, 0, '9A', 'Ukara ing ngisor iki klebu gunane basa ngoko alus, kajaba ....', NULL, 'Kanggo guneman anak marang wong tuwa', NULL, 'Kanggo ngurmati wong tuwa', NULL, 'Kanggo guneman wong tuwa marang wong enom kang drajate luwih dhuwur', NULL, 'Kanggo guneman sapdha-padha wus kulina nanging isih duwe rasa ngurmati', NULL, '', NULL, 'A'),
(5033, 68, 30, 0, '9A', 'Tembung krama kang disingkat kayata : niki, niku, empun, ngga, diwastani ....', NULL, 'Tembung ngoko alus', NULL, 'Tembung krama lugu', NULL, 'Tembung krama alus', NULL, 'Tembung krama madya', NULL, '', NULL, 'D'),
(5034, 68, 30, 0, '9A', 'Ukara-ukara ing ngisor iki pilihen endi sing nggunakake basa ngoko alus ?', NULL, 'Aku arep adus', NULL, 'Bapak wis dhahar', NULL, 'Kula empun nedha kala wau', NULL, 'Dinten menika Pak guru boten rawuh', NULL, '', NULL, 'B'),
(5035, 68, 30, 0, '9A', 'Ukara ing ngisor iki luput unggah-ungguhe kajaba ....', NULL, 'Bu, menawi angsal kulo nyuwun idin badhe kondur', NULL, 'Bu,menawi kepareng kulo nyuwun idin badhe kondur', NULL, 'Bu,menawi kepareng kulo nyuwun idin badhe wangsul', NULL, 'Bu menawi angsal kulo nyuwun idin badhe kondur', NULL, '', NULL, 'C'),
(5036, 68, 30, 0, '9A', 'Sawise tekan ngomah, Shinta anggone caos lapuran marang ibune menawa gaweyane wis ditindakake, ature ....', NULL, 'Bu kulo sampun kepanggih Bu Dukuh lan sampun omong menawi ibu boten saged tindak', NULL, 'Bu kulo sampun kepanggih Bu Dukuh lan sampun sanjang menawi ibu boten saged tindak', NULL, 'Bu kulo sampun kepanggih Bu Dukuh lan sampun ngendika menawi ibu boten saged tindak', NULL, 'Bu kulo sampun kepanggih Bu Dukuh lan sampun matur menawi ibu boten saged tindak', NULL, '', NULL, 'D'),
(5037, 68, 30, 0, '9A', 'Ukara sambawa kang maknane pangajab/pangarep-arep yaiku ....', NULL, 'Sugiha dhuwit aku wis mbangun omah', NULL, 'Diwenehana kaos anyar yo aora dianggo', NULL, 'Pintera ya anaku supaya mbesuke kasil uripe', NULL, 'Mangkata mau, saiki wis tekan', NULL, '', NULL, 'C'),
(5038, 68, 30, 0, '9A', 'Kang ora kalebu ukara pangajab ing ngisor iki yaiku ....', NULL, 'Muga-muga biji ujianku mbesuk maremake', NULL, 'Mugi Gusti tansah paring barokah dhateng kita sedaya', NULL, 'Udana sing deres kareben tandurane ora garing', NULL, 'Sinaua sing mempeng supaya lulus', NULL, '', NULL, 'D'),
(5039, 68, 30, 0, '9A', 'Tuladha ukara kanggo nelakake bela sungkawa lan panglipur kang bener ....', NULL, 'Wis rasah digetuni, wong urip bakal mesti mati, kaya bapaku iki !', NULL, 'Aku melu susah muga-muga bapakmu neng alam kaswargan apik-apik wae !', NULL, 'Aku nderek bela sungkawa, muga-muga Dhik Tika tetep tabah lan tawakal, kabeh wis ginaris ana astane Gusti', NULL, 'Aku nderek bela sungkawa satenen-tenane, muga-muga Dhik Tika ora ngalami kahanan kaya ngene iki !', NULL, '', NULL, 'C'),
(5040, 68, 30, 0, '9B', 'Pangertene unggah-ungguh bisa ditegesi ....', NULL, 'Sopan santun', NULL, 'Tata susila', NULL, 'Tata krama', NULL, 'Kabeh jawaban bener', NULL, '', NULL, 'D'),
(5041, 68, 30, 0, '9B', 'Wong srawung mono kudu nggatekake bab-bab ....', NULL, 'Sapa kang diajak srawung', NULL, 'Ing ngendi papan anggone srawung', NULL, 'Kapan wektune', NULL, 'Kabeh wangsulan bener', NULL, '', NULL, 'D'),
(5042, 68, 30, 0, '9B', 'Ukara ing ngisor iki endi kang unggah-ungguhe bener  ?', NULL, 'Pak guru boten mangkat amargi lara', NULL, 'Adhik mundhut sepatu dhateng Wonosari', NULL, 'Bapak wungu jam 5 lajeng siram', NULL, 'Kulo dereng dhahar sekul', NULL, '', NULL, 'C'),
(5043, 68, 30, 0, '9B', 'Wong sing ora gelem ngurmati wong liya iku tegese ....', NULL, 'Ngajeni wong liya', NULL, 'Nguwongake wong liya', NULL, 'Nganggep luwih wong liya', NULL, 'Ngremehake lan nyepelekake wong liya', NULL, '', NULL, 'D'),
(5044, 68, 30, 0, '9B', 'Yen kepingin diajeni wong liya kudune kepriye ...', NULL, 'Sing diajeni wong sing luwih tuwa wae', NULL, 'Nggatekake wong liya yen perlu wae', NULL, 'Ora sah nggatekake marang wong liya', NULL, 'Uga kudu ngajeni wong liya', NULL, '', NULL, 'D'),
(5045, 68, 30, 0, '9B', 'Ukara-ukara ing ngisor iki kang migunakake basa krama lugu yaiku ....', NULL, 'Mas Bambang ora kersa dhahar bakmi goreng', NULL, 'Sampeyan menapa sampun dhahar ?', NULL, 'Bu Guru nembe ngasta wonten ing kelas 9A', NULL, 'Adhiku lagi garap tugas bareng kanca-kancane', NULL, '', NULL, 'D'),
(5046, 68, 30, 0, '9B', 'Gatekna ukara-ukara ing ngisor iki !\n(1) Ajeng teng pundi Lik ?\n(2) Bapak sampun sare\n(3) Dhaharipun sampun cumawis\n(4) Nggene kulo empun telas rumiyin\nEndi ukara kang nandhut tembung madya ?', NULL, '1, 2', NULL, '2, 3', NULL, '3, 4', NULL, '1, 4', NULL, '', NULL, 'D'),
(5047, 68, 30, 0, '9B', 'Ukara ing ngisor iki kang trep unggah-ungguhe ing ukara ....', NULL, 'Nyuwun pangapunten Pak Guru, kala wingi kulo boten saged rawuh', NULL, 'Rayi kula nembe dhahar bakso', NULL, 'Sakonduripun saking dalemipun pakdhe kula lajeng sare', NULL, 'Ibu dhawuh adhik supados nedha rumiyin', NULL, '', NULL, 'D'),
(5048, 68, 30, 0, '9B', 'â€Aku diwenehi dhuwit ibu selawe ewu rupiahâ€\nUkara iki menawa diowahi dadi basa krama kang pener yaiku ....', NULL, 'Kula dipuncaosi arta ibu selangkung ewu rupiyah', NULL, 'Kula dipunparingi arta ibu selangkung ewu rupiyah', NULL, 'Kula diparingi arta ibu selanwe ewu rupiyah', NULL, 'Kula dipuncaosi arta ibu selawe ewu rupiyah', NULL, '', NULL, 'B'),
(5049, 68, 30, 0, '9B', 'Kepriye anggonmu lapuran marang Bu Guru sawise nindakake dhawuhe ngaturake buku marang bapak kepala sekolah ?', NULL, 'Bu Guru, bukunipun sampun kulo aturake Bapak Kepala Sekolah', NULL, 'Bu Guru, bukunipun sampun kulo paringaken Bapak Kepala Sekolah', NULL, 'Bu Guru, bukunipun sampun kulo sukakaken Bapak Kepala Sekolah', NULL, 'Bu Guru, bukunipun sampun kulo caosaken Bapak Kepala Sekolah', NULL, '', NULL, 'D'),
