(5173, 61, 15, 14, '9B', 'Seorang perempuan mengalami pematangan sel telur di ovarium. Apabila sel telur yang telah matang tersebut tidak dibuahi oleh sperma, peristiwa yang akan terjadi selanjutnya adalah ....', NULL, 'Dinding rahim semakin menebal untuk mempertahankan kehamilan.', NULL, 'Sel telur berkembang menjadi embrio di dalam tuba falopi.', NULL, 'Kadar hormon tertentu menurun sehingga lapisan dinding rahim meluruh dan terjadi menstruasi.', NULL, 'Ovarium berhenti menghasilkan sel telur secara permanen.', NULL, '', NULL, 'C'),
(5175, 61, 15, 24, '9B', 'Berdasarkan pola siklus menstruasi berikut ini, Fase ovulasi terjadi ketika ....', 'img_6ad2e03b915af.png', 'kadar estrogen meningkat dan diikuti lonjakan hormon LH secara mendadak.', NULL, 'kadar estrogen dan progesteron menurun hingga lapisan dinding rahim meluruh.', NULL, 'kadar FSH meningkat dan merangsang pematangan folikel di ovarium.', NULL, 'kadar progesteron meningkat untuk mempertahankan ketebalan dinding rahim.', NULL, '', NULL, 'C'),
