(5226, 60, 14, 0, '9B', 'Berikut ini adalah definisi yang benar tentang algoritma, kecuali ...', NULL, 'serangkaian langkah yang berurutan untuk menyelesaikan masalah', NULL, 'serangkaian kode program untuk mengolah input menjadi output', NULL, 'serangkaian instruksi untuk menyelesaikan permasalahan komputasi', NULL, 'Sekumpulan aturan yang secara tepat mendefinisikan urutan langkah-langkah operasi', NULL, '', NULL, 'B'),
(5227, 60, 14, 0, '9B', 'Manakah yang termasuk beberapa kegunaan dari algoritma?', NULL, 'Untuk menjelaskan serangkaian operasi atau prosedur', NULL, 'Untuk menjelaskan serangkaian langkah dalam menyelesaikan permasalahan', NULL, 'Untuk menggambarkan bagaimana komputer mengolah data input menjadi output', NULL, 'Sebagai panduan programmer untuk mengimplementasikan sebuah metode penyelesaian masalah ke dalam kode program', NULL, '', NULL, 'D'),
(5228, 60, 14, 0, '9B', 'Apa perbedaan utama antara metode LIFO (Tumpukan) dan FIFO (Antrean) dalam pengelolaan data oleh komputer?', NULL, 'LIFO mengambil data terakhir yang masuk terlebih dahulu, sedangkan FIFO mengambil data pertama yang masuk terlebih dahulu.', NULL, 'B. LIFO mengambil data secara acak, sedangkan FIFO mengambil data secara berurutan', NULL, 'LIFO hanya digunakan untuk gambar, sedangkan FIFO hanya untuk teks.', NULL, 'LIFO dan FIFO tidak digunakan dalam komputer.', NULL, '', NULL, 'A'),
(5229, 60, 14, 0, '9B', 'Sebuah loker digital di sekolah hanya dapat dibuka jika PIN benar DAN kartu akses terdeteksi.\r\nPerhatikan kondisi berikut:\r\n- PIN yang dimasukkan benar.\r\n- Kartu akses tidak terdeteksi.\r\nApa yang terjadi?', 'img_6ad3117c1a532.png', 'Loker terbuka karena PIN benar.', NULL, 'Loker tetap terkunci karena salah satu syarat belum terpenuhi.', NULL, 'Loker terbuka karena cukup satu syarat benar.', NULL, 'Loker terbuka secara otomatis setelah PIN dimasukkan.', NULL, '', NULL, 'B'),
(5230, 60, 14, 0, '9B', 'Saat dalam atrian maka struktur data yang queue yang digunakan adalahâ€¦', 'img_6ad31136627e9.jpg', 'Queue mengikuti prinsip Last In First ocode and flowcharts Out (LIFO).', NULL, 'Queue tidak bisa digunakan untuk menyimpan data.', NULL, 'Queue mengikuti prinsip First In First Out (FIFO).', NULL, 'Queue adalah struktur data yang tidak memiliki urutan', NULL, '', NULL, 'C'),
(5231, 60, 14, 0, '9B', 'Manakah dari contoh berikut yang paling tepat menggambarkan penerapan struktur data stack dalam kehidupan sehari-hari?', NULL, 'Menulis catatan pada kertas, lalu menghapusnya setelah beberapa hari.', NULL, 'Menyusun piring di dapur, dengan piring yang terakhir diletakkan di atas yang pertama kali diambil.', NULL, 'Mengantri di kasir untuk membayar barang.', NULL, 'Menyusun buku di rak, dengan buku yang paling bawah diambil pertama.', NULL, '', NULL, 'B'),
