(5306, 60, 12, 0, '7B', 'Urutkan langkah-langkah dalam anatomi perjalanan satu klik dari mulai sentuh antarmuka hingga tampil hasil.', NULL, 'Sentuh Antarmuka, Jalankan Peramban, Ketik Kata Kunci, crawling, Pengindeksan, Tampil Hasil', NULL, 'Ketik Kata Kunci, Sentuh Antarmuka, Jalankan Peramban, Pengindeksan, crawling, Tampil Hasil', NULL, 'Jalankan Peramban, Sentuh Antarmuka, Ketik Kata Kunci, Pengindeksan, crawling, Tampil Hasil', NULL, 'Sentuh Antarmuka, Ketik Kata Kunci, Jalankan Peramban, crawling, Pengindeksan, Tampil Hasil', NULL, '', NULL, 'A'),
