(5308, 60, 12, 0, '7B', 'Apa langkah-langkah yang harus dilakukan untuk membuka dokumen kosong di Microsoft Word?', NULL, 'Klik logo Windows, ketik Word, pilih ikon Word dan Blank Document', NULL, 'Klik ikon Word, ketik dokumen, pilih Start', NULL, 'Klik Start, pilih dokumen, ketik Word', NULL, 'Ketik Word, klik Start, pilih ikon Word', NULL, '', NULL, 'A'),
