(5422, 59, 9, 0, '7B', 'Suatu persegi panjang dengan panjang = (3x+1) cm dan lebar = ( x+2) cm. jika luas persegi panjang tersebut panjang dikalikan dengan lebarnya, maka luas persegi panjang tersebut adalah â€¦.', NULL, '.', 'img_6ad56eb8f3b5a.png', '.', 'img_6ad56eb8f3d06.png', '.', 'img_6ad56eb8f3e12.png', '.', 'img_6ad56eb8f3f03.png', '', NULL, 'A'),
(5507, 70, 32, 0, '7A', 'Lokasi absolut adalah lokasi suatu tempat yang ditentukan berdasarkan ....', NULL, 'Kondisi lingkungan di sekitarnya', NULL, 'Letak suatu tempat terhadap tempat lain', NULL, 'Garis lintang dan garis bujur', NULL, 'Jarak suatu tempat dari pusat kota', NULL, '', NULL, 'C'),
(5508, 70, 32, 0, '7A', 'Lokasi relatif adalah lokasi suatu tempat yang ditentukan berdasarkan ....', NULL, 'Garis lintang dan garis bujur', NULL, 'Letak suatu tempat terhadap tempat lain di sekitarnya', NULL, 'Koordinat geografis suatu wilayah', NULL, 'Posisi suatu tempat berdasarkan garis khatulistiwa', NULL, '', NULL, 'B'),
(5509, 70, 32, 0, '7A', 'Perhatikan ilustrasi berikut!\nRina ingin mengunjungi rumah temannya. Ia mendapat petunjuk bahwa rumah tersebut berada di belakang kantor kelurahan, bersebelahan dengan masjid, dan dekat dengan pasar.\nBerdasarkan ilustrasi tersebut, konsep lokasi yang digunakan untuk menunjukkan letak rumah teman Rina adalah ....', NULL, 'Lokasi relatif, karena menunjukkan letak berdasarkan tempat lain di sekitarnya', NULL, 'Lokasi absolut, karena menggunakan titik koordinat', NULL, 'Lokasi astronomis, karena menggunakan garis lintang dan garis bujur', NULL, 'Lokasi geografis, karena menunjukkan letak berdasarkan koordinat wilayah', NULL, '', NULL, 'A'),
(5510, 70, 32, 0, '7A', 'Manakah contoh nyata dari lokasi absolut?', NULL, 'Rumah Andi berada di sebelah utara sekolah', NULL, 'Pasar tradisional terletak dekat dengan terminal', NULL, 'Indonesia terletak pada koordinat 6Â° LUâ€“11Â° LS dan 95Â° BTâ€“141Â° BT', NULL, 'Rumah Siti berada tidak jauh dari kantor desa', NULL, '', NULL, 'C'),
(5511, 70, 32, 0, '7A', 'Peta digital adalah peta yang disajikan dalam bentuk ....', NULL, 'Gambar yang dibuat di atas kertas menggunakan pensil', NULL, 'Gambar permukaan bumi yang dibuat secara manual', NULL, 'Data atau gambar peta yang ditampilkan melalui perangkat elektronik', NULL, 'Lukisan wilayah yang dibuat berdasarkan imajinasi', NULL, '', NULL, 'C'),
(5512, 70, 32, 0, '7A', 'Sebutkan tiga contoh aplikasi peta digital yang dapat digunakan untuk mencari lokasi dan menunjukkan arah perjalanan!', NULL, 'Google Maps, Excel, dan Apple Maps', NULL, 'Google Maps, Waze, dan Apple Maps', NULL, 'WhatsApp, Google Maps, Apple Maps', NULL, 'YouTube, TikTok, dan Canva', NULL, '', NULL, 'B'),
(5513, 70, 32, 0, '7A', 'Perhatikan situasi berikut!\nAndi akan pergi ke rumah saudaranya di kota yang belum pernah ia kunjungi. Ia menggunakan peta digital untuk mencari lokasi tujuan, melihat kondisi jalan, dan memilih rute yang paling sesuai agar dapat sampai dengan cepat.\nBerdasarkan situasi tersebut, manfaat peta digital yang paling tepat adalah ....', NULL, 'Menunjukkan kondisi suatu wilayah tanpa membutuhkan data atau informasi geografis.', NULL, 'Menggantikan seluruh fungsi peta cetak dalam pembelajaran geografi.', NULL, 'Menentukan letak suatu wilayah berdasarkan garis lintang dan garis bujur saja.', NULL, 'Membantu pengguna menemukan lokasi dan memilih rute perjalanan berdasarkan informasi geografis yang tersedia.', NULL, '', NULL, 'D'),
(5514, 70, 32, 0, '7A', 'Andi akan melakukan perjalanan dari rumahnya menuju museum di kota lain. Ia belum mengetahui jalan yang harus dilalui dan ingin menghindari kemacetan agar tiba tepat waktu. Andi menggunakan aplikasi peta digital. Manfaat peta digital yang paling tepat untuk membantu Andi adalah ....', NULL, 'Mengetahui sejarah museum dan kebudayaan masyarakat di sekitarnya', NULL, 'Menentukan rute perjalanan, memperkirakan waktu tempuh, dan memantau kondisi lalu lintas', NULL, 'Mengetahui jumlah penduduk dan mata pencaharian masyarakat di kota tujuan', NULL, 'Mengukur tingkat pendidikan dan pendapatan penduduk di sepanjang perjalanan', NULL, '', NULL, 'B'),
(5515, 70, 32, 0, '7A', 'Konektivitas antarruang adalah ....', NULL, 'Perbedaan kondisi alam dan budaya yang terdapat di setiap wilayah', NULL, 'Hubungan antara satu ruang dengan ruang lainnya yang saling memengaruhi melalui interaksi dan pergerakan manusia, barang, atau informasi', NULL, 'Proses perubahan bentuk permukaan bumi akibat tenaga alam', NULL, 'Kegiatan manusia dalam memanfaatkan sumber daya alam di lingkungan sekitarnya', NULL, '', NULL, 'B'),
(5516, 70, 32, 0, '7A', 'Tiga faktor yang memengaruhi terjadinya interaksi antarwilayah adalah ....', NULL, 'Faktor geografis, faktor ekonomi, faktor sosial budaya', NULL, 'Faktor geografis, faktor ekonomi, faktor genetik', NULL, 'Faktor sosial budaya, faktor ekonomi, faktor genetik', NULL, 'Faktor sosial budaya, faktor ekonomi, faktor pribadi', NULL, '', NULL, 'A'),
(5517, 70, 32, 0, '7A', 'Apa perbedaan interaksi antara wilayah pedesaan dan perkotaan?', NULL, 'Pedesaan lebih banyak menyediakan hasil pertanian, sedangkan perkotaan menyediakan barang, jasa, dan lapangan pekerjaan', NULL, 'Penduduk pedesaan lebih padat, sedangkan perkotaan lebih sedikit', NULL, 'Infrastruktur di wilayah perkotaan seringkali terbatas, sedangkan di wilayah pedesaan lebih maju', NULL, 'Rumah-rumah di pedesaan biasanya cenderung lebih padat, sedangkan di perkotaan biasanya tersebar dengan jarak cukup jauh satu sama lain', NULL, '', NULL, 'A'),
(5518, 70, 32, 0, '7A', 'Wilayah pedesaan berinteraksi dengan wilayah perkotaan karena desa â€¦.', NULL, 'Merupakan pusat industri besar', NULL, 'Memiliki fasilitas pendidikan dan kesehatan yang lengkap', NULL, 'Menyediakan bahan pangan dan bahan mentah untuk kota', NULL, 'Menjadi pusat pemerintahan negara', NULL, '', NULL, 'C'),
(5519, 70, 32, 0, '7A', 'Wilayah perkotaan membutuhkan wilayah pedesaan karena â€¦', NULL, 'kota memerlukan bahan pangan dan tenaga kerja', NULL, 'kota tidak memiliki tempat wisata', NULL, 'kota lebih maju dibandingkan pedesaan', NULL, 'kota lebih padat penduduk dibandingkan desa', NULL, '', NULL, 'A'),
(5520, 70, 32, 0, '7A', 'Apa yang dimaksud dengan iklim?', NULL, 'Keadaan udara pada suatu tempat dalam waktu yang sangat singkat', NULL, 'Rata-rata kondisi cuaca dalam jangka waktu yang panjang di suatu wilayah', NULL, 'Perubahan suhu udara yang terjadi setiap jam', NULL, 'Keadaan lingkungan yang hanya dipengaruhi oleh curah hujan', NULL, '', NULL, 'B'),
(5521, 70, 32, 0, '7A', '3 jenis iklim di Indonesia adalah â€¦.', NULL, 'Iklim hujan, iklim tropis, iklim kemarau', NULL, 'Iklim tropis hujan, iklim tropis muson, iklim kemarau', NULL, 'Iklim Laut, Iklim Topis, Iklim Salju', NULL, 'Iklim tropis hujan, iklim tropis muson, iklim Laut', NULL, '', NULL, 'D'),
(5522, 70, 32, 0, '7A', 'Perhatikan kasus berikut!\nDalam beberapa tahun terakhir, petani di suatu daerah mengalami kesulitan menentukan waktu tanam. Musim hujan datang lebih lambat dari biasanya, sementara suhu udara semakin meningkat. Akibatnya, hasil panen menurun dan persediaan pangan menjadi berkurang.\nBerdasarkan kasus tersebut, dampak perubahan iklim yang paling tepat adalah ....', NULL, 'Perubahan pola musim dan penurunan hasil pertanian', NULL, 'Bertambahnya luas lahan pertanian dan meningkatnya hasil panen', NULL, 'Menurunnya suhu udara dan meningkatnya ketersediaan air', NULL, 'Bertambahnya curah hujan sepanjang tahun dan meningkatnya hasil panen', NULL, '', NULL, 'A'),
(5523, 70, 32, 0, '7A', 'Dalam beberapa tahun terakhir, suatu daerah mengalami musim hujan yang tidak menentu, suhu udara semakin panas, dan banjir lebih sering terjadi. Kondisi tersebut dapat menjadi dampak dari perubahan iklim. Manakah dampak perubahan iklim yang paling tepat berdasarkan kondisi tersebut?', NULL, 'Menurunnya permukaan laut, berkurangnya suhu udara, dan meningkatnya kestabilan musim.', NULL, 'Meningkatnya kesuburan tanah, bertambahnya sumber air bersih, dan berkurangnya bencana alam', NULL, 'Bertambahnya luas hutan, menurunnya suhu bumi, dan bertambahnya curah hujan ekstrem.', NULL, 'Perubahan pola musim, peningkatan suhu bumi, dan meningkatnya risiko bencana seperti banjir.', NULL, '', NULL, 'D'),
(5524, 70, 32, 0, '7A', 'Bagaimana kondisi geologis Indonesia berkaitan dengan potensi terjadinya bencana alam?', NULL, 'Indonesia berada di wilayah yang stabil sehingga jarang terjadi bencana alam.', NULL, 'Indonesia memiliki potensi bencana banjir karena sebagian besar wilayahnya berupa dataran rendah.', NULL, 'Indonesia berada di pertemuan beberapa lempeng tektonik sehingga memiliki potensi gempa bumi, tsunami, dan aktivitas gunung api.', NULL, 'Indonesia tidak memiliki gunung api aktif karena berada jauh dari batas lempeng tektonik.', NULL, '', NULL, 'C'),
(5525, 70, 32, 0, '7A', 'Bencana alam apa saja yang sesuai dengan kondisi geologis Indonesia?', NULL, 'Tsunami, Gempa bumi, dan letusan gunung api', NULL, 'Badai salju, tornado, dan longsoran es', NULL, 'Kekeringan, badai salju, dan tsunami', NULL, 'Tornado, gempa bumi, dan badai salju', NULL, '', NULL, 'A'),
(5526, 70, 32, 0, '7A', 'Indonesia memiliki potensi gempa bumi yang tinggi karena â€¦', NULL, 'Terletak disekitar garis khatulistiwa', NULL, 'Berada di antara tiga lempeng tektonik utama dunia', NULL, 'Memiliki banyak sungai besar yang melintasi wilayahnya', NULL, 'Sebagian besar wilayahnya berupa dataran rendah', NULL, '', NULL, 'B'),
(5527, 70, 32, 0, '7A', 'Apa yang dimaksud dengan kegiatan ekonomi?', NULL, 'Kegiatan manusia untuk berinteraksi dan berkomunikasi dengan orang lain', NULL, 'Kegiatan manusia untuk melakukan perjalanan dari satu tempat ke tempat lain', NULL, 'Kegiatan manusia untuk menjaga kelestarian lingkungan tanpa menghasilkan barang atau jasa', NULL, 'Kegiatan manusia untuk memenuhi kebutuhan hidup', NULL, '', NULL, 'D'),
(5528, 70, 32, 0, '7A', 'Apa yang dimaksud dengan produksi?', NULL, 'Kegiatan menghasilkan atau menambah nilai guna barang dan jasa untuk memenuhi kebutuhan manusia.', NULL, 'Kegiatan menggunakan barang atau jasa untuk memenuhi kebutuhan hidup.', NULL, 'Kegiatan menyalurkan barang atau jasa dari produsen kepada konsumen.', NULL, 'Kegiatan membeli barang dan jasa untuk dijual kembali kepada orang lain.', NULL, '', NULL, 'A'),
(5529, 70, 32, 0, '7A', 'Apa yang dimaksud dengan distribusi?', NULL, 'Kegiatan menghasilkan barang dan jasa untuk memenuhi kebutuhan manusia.', NULL, 'Kegiatan menyimpan barang untuk digunakan sendiri.', NULL, 'Kegiatan menyalurkan barang atau jasa dari produsen kepada konsumen.', NULL, 'Kegiatan menggunakan barang dan jasa untuk memenuhi kebutuhan hidup.', NULL, '', NULL, 'C'),
(5530, 70, 32, 0, '7A', 'Apa yang dimaksud dengan konsumsi?', NULL, 'Kegiatan menghasilkan barang atau jasa untuk memenuhi kebutuhan manusia.', NULL, 'Kegiatan menyalurkan barang atau jasa dari produsen kepada konsumen.', NULL, 'Kegiatan menyimpan barang untuk dijual kembali kepada konsumen.', NULL, 'Kegiatan menggunakan atau menghabiskan barang dan jasa untuk memenuhi kebutuhan hidup.', NULL, '', NULL, 'D'),
(5531, 70, 32, 0, '7A', 'Perhatikan beberapa kegiatan berikut!\n1. Ibu membuat kue untuk dijual di warung.\n2. Rani membeli buku untuk digunakan belajar.\n3. Pak Budi mengantarkan hasil panen ke pasar untuk dijual.\n4. Siti membuat kerajinan tangan dari bahan bekas dan menjualnya secara daring.\nKegiatan yang termasuk produksi ditunjukkan oleh nomor ....', NULL, '3 dan 4', NULL, '2 dan 3', NULL, '1 dan 2', NULL, '1 dan 4', NULL, '', NULL, 'D'),
(5532, 70, 32, 0, '7A', 'Perhatikan beberapa kegiatan berikut!\n1. Pak Andi mengangkut sayuran dari petani ke pasar untuk dijual.\n2. Ibu membeli beras untuk dimasak menjadi nasi.\n3. Sebuah toko online mengirimkan pakaian dari gudang kepada pembeli.\n4. Rina membuat kue untuk dijual di kantin sekolah.\nKegiatan yang termasuk distribusi ditunjukkan oleh nomor ....', NULL, '1 dan 2', NULL, '3 dan 4', NULL, '1 dan 3', NULL, '2 dan 4', NULL, '', NULL, 'C'),
(5533, 70, 32, 0, '7A', 'Perhatikan beberapa kegiatan berikut!\n1. Ayah membeli bensin untuk digunakan bepergian ke kantor.\n2. Ibu membuat kue untuk dijual di pasar.\n3. Rani menggunakan buku dan alat tulis untuk belajar.\n4. Pak Dedi mengantarkan barang dari gudang ke toko.\nKegiatan yang termasuk konsumsi ditunjukkan oleh nomor ....', NULL, '1 dan 3', NULL, '1 dan 2', NULL, '2 dan 4', NULL, '3 dan 4', NULL, '', NULL, 'A'),
(5534, 70, 32, 0, '7A', 'Apa yang dimaksud dengan interaksi sosial?', NULL, 'Kegiatan manusia untuk memenuhi kebutuhan hidup melalui kegiatan ekonomi', NULL, 'Hubungan timbal balik antara individu dengan individu, individu dengan kelompok, atau kelompok dengan kelompok', NULL, 'Kegiatan manusia dalam memanfaatkan sumber daya alam di lingkungan sekitar', NULL, 'Proses perpindahan penduduk dari satu wilayah ke wilayah lainnya', NULL, '', NULL, 'B'),
(5535, 70, 32, 0, '7A', 'Apa saja syarat terjadinya interaksi sosial?', NULL, 'Kontak sosial dan komunikasi', NULL, 'Kerja sama dan persaingan', NULL, 'Produksi dan konsumsi', NULL, 'Simpati dan empati', NULL, '', NULL, 'A'),
(5536, 70, 32, 0, '7A', 'Apa saja bentuk-bentuk interaksi sosial?', NULL, 'Produksi, distribusi, dan konsumsi', NULL, 'Simpati, empati, dan motivasi', NULL, 'Kontak sosial dan komunikasi', NULL, 'Kerja sama, persaingan, dan konflik', NULL, '', NULL, 'D'),
