(5649, 59, 10, 3, '8B', 'Rumus suku ke-n pada barisan 4, 11, 18, 25, ...\nadalah ..', NULL, '7n', NULL, '7n+3', NULL, '7n-3', NULL, '7(n-3)', NULL, '', NULL, 'C'),
(5650, 59, 10, 2, '8B', 'Rumus suku ke-n baris bilangan 5, 8, 11, 14, 17, ...\nadalah..', NULL, 'Un = 3n + 5', NULL, 'Un = 3n + 2', NULL, 'Un = 3n â€“ 1', NULL, 'Un = 3 (n â€” 2)', NULL, '', NULL, 'B'),
(5651, 59, 10, 6, '8B', 'Sebuah keluarga memiliki 6 orang anak. Setiap anak memiliki selisih 3 tahun. Jika usia anak paling muda 13 tahun, maka berapa usia anak paling tua?', NULL, '28 tahun', NULL, '27 tahun', NULL, '26 tahun', NULL, '25 tahun', NULL, '', NULL, 'A'),
(5652, 59, 10, 13, '8B', 'Di dalam aula terdapat susunan kursi, baris pertamma 20 kursi, baris kedua 22 kursi, baris ketiga 24 kursi demikian seterusnya, dalam aula tersebut terdapat 10 baris kursi. Berapa jumlah seluruh kursi pada gedung tersebut?', NULL, '290', NULL, '280', NULL, '270', NULL, '260', NULL, '', NULL, 'A'),
