(5664, 59, 10, 1, '8B', 'fungsi f dinyatakan dengan rumus f(x) = ax + b. Jika f(4) = 19 dan f(2) = 7, maka bentuk fungsi tersebut adalahâ€¦.', NULL, 'f(x) = 6x â€“ 5', NULL, 'f(x) = 6x + 5', NULL, 'f(x) = -6x â€“ 5', NULL, 'f(x) = -6x + 42', NULL, '', NULL, 'A'),
